  e_cash: ["Dinheiro vivo", "Cash", "Efectivo"], e_fuel: ["Combustível", "Fuel", "Combustible"], e_water: ["Água guardada", "Stored water", "Agua guardada"], e_food: ["Comida que não estraga", "Non-perishable food", "Comida no perecible"],
