  // v0.2 — objetivo, dicas de onde achar, mochila explicada, rádio, água não tratada, apartamento
  objMain: ["🎯 Objetivo principal: ficar em casa em segurança. Prepare o apartamento para 72 horas antes do apagão.", "🎯 Main goal: shelter in place. Get your apartment ready for 72 hours before the blackout.", "🎯 Objetivo principal: quedarte en casa seguro. Prepara el apartamento para 72 horas antes del apagón."],
  objAfter: ["🎯 Objetivo: aguentar em casa até a hora 72 (faltam {h} h). Saia só quando precisar.", "🎯 Goal: hold out at home until hour 72 ({h} h left). Go out only when needed.", "🎯 Objetivo: aguantar en casa hasta la hora 72 (faltan {h} h). Sal solo si es necesario."],
