  h_light: ["🔦 Lanterna: estante da sala · 🔋 Pilhas: mercado", "🔦 Flashlight: living-room shelf · 🔋 Batteries: market", "🔦 Linterna: estante de la sala · 🔋 Pilas: mercado"],
  h_radio: ["📻 Rádio: estante da sala · 🔋 Pilhas: mercado", "📻 Radio: living-room shelf · 🔋 Batteries: market", "📻 Radio: estante de la sala · 🔋 Pilas: mercado"],
